<script setup lang="ts">
import { computed } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { useRouter } from 'vue-router'
import { Document, MagicStick, Warning, Calendar, ArrowRight, Plus, Wallet, Files } from '@element-plus/icons-vue'
import { api } from '../api/client'
import { useSession } from '../stores/session'
import PageHeader from '../components/PageHeader.vue'
import StatusTag from '../components/StatusTag.vue'
const session=useSession(),router=useRouter()
const summary=useQuery({queryKey:computed(()=>['summary',session.tenant]),queryFn:()=>api('/dashboard/summary','get',{tenant:session.tenant})})
const invoices=useQuery({queryKey:computed(()=>['invoices',session.tenant,'recent']),queryFn:()=>api('/invoices','get',{tenant:session.tenant,params:{page_size:4}})})
const cards=computed(()=>[{title:'待入账发票',value:summary.data.value?.pending,unit:'张',note:'核对建议后即可入账',icon:MagicStick,tone:'blue',path:'/posting'},{title:'待申报任务',value:summary.data.value?.filings,unit:'项',note:'申报模块待接入',icon:Calendar,tone:'violet',path:'/filings'},{title:'待处理风险',value:summary.data.value?.risks,unit:'项',note:'关注异常，及时核查',icon:Warning,tone:'orange',path:'/risks'},{title:'本月采集发票',value:summary.data.value?.invoices,unit:'张',note:'本期累计采集数量',icon:Document,tone:'teal',path:'/invoices'}])
const shortcuts=[{label:'模拟导入',detail:'采集样例发票',icon:Plus,path:'/invoices?import=1'},{label:'智能入账',detail:'查看科目建议',icon:MagicStick,path:'/posting'},{label:'费用报销',detail:'查看报销记录',icon:Wallet,path:'/reimbursements'},{label:'电子档案',detail:'了解归档进度',icon:Files,path:'/archives'}]
const totalTrend=computed(()=>summary.data.value?.trend.reduce((total,row)=>total+row.input+row.output,0)||0)
</script>
<template><div><PageHeader title="工作台概览" description="每一笔业务，心中有数。"><span class="period-control"><el-icon><Calendar/></el-icon>2026 年 11 月<span class="demo-label">演示期间</span></span></PageHeader><section class="welcome-banner"><div><div class="welcome-kicker">YOUR FINANCE, IN FOCUS</div><h2>{{session.me?.role==='viewer'?'欢迎查看财税工作台':'你好，今天也让财税工作井然有序。'}}</h2><p>从票据到凭证，在一个工作空间完成日常财务处理。</p><el-button type="primary" @click="router.push('/posting')">查看待办任务 <el-icon><ArrowRight/></el-icon></el-button></div><div class="hero-art" aria-hidden="true"><div class="art-circle"/><div class="art-sheet rear"><span/><span/><span/></div><div class="art-sheet front"><div class="art-icon">¥</div><b>票 · 账 · 税</b><span/><span/><div class="art-check">✓</div></div><div class="art-badge">✦ 智能协同</div></div></section><el-alert v-if="summary.error.value" :title="summary.error.value.message" type="error" show-icon :closable="false"><el-button link @click="summary.refetch()">重试</el-button></el-alert><div class="metrics" v-loading="summary.isPending.value"><button class="metric-card" v-for="card in cards" :key="card.title" @click="router.push(card.path)"><div class="metric-top"><span>{{card.title}}</span><span class="metric-icon" :class="card.tone"><el-icon><component :is="card.icon"/></el-icon></span></div><div class="metric-value">{{card.value??'—'}}<span>{{card.unit}}</span></div><div class="metric-bottom">{{card.note}}<span>↗</span></div></button></div><div class="dashboard-grid"><section class="panel trend-panel"><div class="panel-heading"><div><h2>票据采集趋势</h2><p>近六个月进销项发票数量 · 合成样例</p></div><span class="chart-range">近六个月</span></div><div class="chart-summary"><strong>{{totalTrend}}</strong><span>张 / 六个月累计</span><div class="chart-legend"><i class="input"/>进项发票<i class="output"/>销项发票</div></div><div class="bar-chart" role="img" :aria-label="summary.data.value?.trend.map(r=>`${r.month}进项${r.input}张，销项${r.output}张`).join('；')"><div class="chart-y"><span>30</span><span>20</span><span>10</span><span>0</span></div><div class="chart-plot"><div class="chart-gridlines"><i/><i/><i/><i/></div><div v-for="row in summary.data.value?.trend" :key="row.month" class="chart-group"><div class="bar-pair"><div class="bar input" :style="{height:`${row.input/30*100}%`}" :title="`进项 ${row.input} 张`"/><div class="bar output" :style="{height:`${row.output/30*100}%`}" :title="`销项 ${row.output} 张`"/></div><span>{{row.month}}</span></div></div></div></section><section class="panel todo-panel"><div class="panel-heading"><h2>我的待办</h2><span class="small-muted">本期工作</span></div><button class="todo-item" @click="router.push('/posting')"><span class="todo-icon blue"><el-icon><MagicStick/></el-icon></span><span><strong>入账建议待确认</strong><small>查看推荐科目与匹配依据</small></span><b>{{summary.data.value?.pending??'—'}}</b><el-icon><ArrowRight/></el-icon></button><button class="todo-item" @click="router.push('/risks')"><span class="todo-icon orange"><el-icon><Warning/></el-icon></span><span><strong>风险事项待处理</strong><small>核查异常并记录处置过程</small></span><b>{{summary.data.value?.risks??'—'}}</b><el-icon><ArrowRight/></el-icon></button><div class="workflow-note"><span>✧</span><div><strong>入账之前，多一份确定</strong><p>展开建议依据，核对规则命中、历史一致性与字段完整度。</p></div></div></section><section class="panel recent-panel"><div class="panel-heading"><div><h2>最近采集的发票</h2><p>查看票据处理进度</p></div><el-button link type="primary" @click="router.push('/invoices')">全部发票 <el-icon><ArrowRight/></el-icon></el-button></div><el-alert v-if="invoices.error.value" :title="invoices.error.value.message" type="error" :closable="false"/><el-table v-else :data="invoices.data.value?.items||[]" v-loading="invoices.isPending.value"><el-table-column label="交易对方" prop="partner" min-width="200"/><el-table-column label="价税合计" align="right" min-width="125"><template #default="{row}"><span class="money">¥ {{row.total}}</span></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column width="70"><template #default="{row}"><el-button link type="primary" @click="router.push(`/invoices/${row.id}`)">详情</el-button></template></el-table-column></el-table></section><section class="panel shortcuts-panel"><div class="panel-heading"><h2>快捷入口</h2><span class="small-muted">常用功能</span></div><div class="shortcuts"><button v-for="item in shortcuts" :key="item.label" @click="router.push(item.path)"><span><el-icon><component :is="item.icon"/></el-icon></span><strong>{{item.label}}</strong><small>{{item.detail}}</small></button></div></section></div></div></template>
